import fixtureJson from '../../oracles/fixtures/statistics-rate-standardization.json';
import {decodeOracleFixture} from '../../oracles/oracle-fixture';

/** Global Moran_Rate quantities of one dataset. */
export type RateMoranReference = {
  I: number;
  EI: number;
  zNorm: number;
  zRand: number;
  pNorm: number;
  pRand: number;
};

/**
 * esda 2.10 / libpysal 4.15 references generated by
 * `test/oracles/statistics-rate-standardization.py` (see its docstring for the scene). Invalid rows
 * of the `missing` dataset are NaN in `eventsMissing`, `missingZ` and `missingLocalI`; `*Statistics`
 * are `[n, b, s2, a, totalPopulation]`.
 */
export type RateReference = {
  events: number[];
  population: number[];
  island: number;
  invalidRows: Record<string, string>;
  eventsMissing: number[];
  populationMissing: number[];
  eventsUnder: number[];
  populationUnder: number[];
  fullZ: number[];
  fullStatistics: number[];
  missingZ: number[];
  missingStatistics: number[];
  underZ: number[];
  underStatistics: number[];
  fullNegativeVarianceRows: number;
  underNegativeVarianceRows: number;
  fullMoran: RateMoranReference;
  fullLocalI: number[];
  missingMoran: RateMoranReference;
  missingLocalI: number[];
};

const fixture = decodeOracleFixture<{
  generator: string;
  versions: Record<string, string>;
  tolerances: Record<string, unknown>;
  reference: RateReference;
}>(fixtureJson);

/** The esda reference values. */
export const RATE_REFERENCE = fixture.reference;
